extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve aprirsi senza errori"):
		return
	var walls := find_by_name(main, "Walls") as TileMapLayer
	if not check("walls_exists", walls != null, "Nella scena serve un nodo TileMapLayer chiamato Walls"):
		return
	var ts = get_prop(walls, "tile_set") as TileSet
	if not check("tileset_exists", ts != null, "Il nodo Walls deve avere un TileSet assegnato"):
		return
	check("tile_size", ts.tile_size == Vector2i(16, 16), "La dimensione tessere del TileSet deve essere Vector2i(16, 16)")
	var col_layer: int = ts.get_physics_layer_collision_layer(0)
	check("physics_layer", col_layer == 2, "Il Physics Layer 0 del TileSet deve avere Collision Layer impostato a 2 (trovato %d)" % col_layer)

